<style>
/* Installation UI — shared across Index/Create/Edit/Show; Delivery visual language */
.installation-table-wrap,.installation-table-wrap.table-wrap{overflow-x:auto;border:1px solid #e5e7eb;border-radius:8px}
.installation-table{width:100%;min-width:1000px;border-collapse:collapse;table-layout:auto}
.installation-table thead th{padding:13px 14px;background:#f9fafb;color:#374151;font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.5px;text-align:left;white-space:nowrap;border:1px solid #e5e7eb}
.installation-table tbody td{padding:13px 14px;font-size:12px;color:#17284f;border:1px solid #e5e7eb;vertical-align:middle}
.installation-table tbody tr:hover{background:#f8fafc}.installation-table th:first-child,.installation-table td:first-child{width:55px;text-align:center}.installation-table th:last-child,.installation-table td:last-child{text-align:center}
.installation-table .table-actions{display:flex;align-items:center;justify-content:center;gap:7px}.installation-table .table-actions form{display:inline-flex;margin:0!important}
.installation-table .action-btn{width:34px;height:34px;display:inline-flex;align-items:center;justify-content:center;border:1px solid #e5e7eb;border-radius:7px;background:white;text-decoration:none;cursor:pointer;padding:7px}
.installation-table .action-btn svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.installation-table .action-btn.view{color:#2563eb}.installation-table .action-btn.edit{color:#d97706}.installation-table .action-btn.delete{color:#dc2626}
.installation-table .col-location{min-width:220px}.installation-table .col-actions{min-width:145px}.installation-table .col-delivery{min-width:160px}
.installation-link{color:#176d97;font-weight:700;text-decoration:none}.installation-link:hover{text-decoration:underline}
.installation-filter-bar{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:18px}.installation-filter-search{flex:1 1 250px;min-width:190px}
.installation-filter-bar input,.installation-filter-bar select{height:40px;max-width:100%;padding:0 12px;border:1px solid #d9dee8;border-radius:8px;background:#fff;color:#34415c;font-size:12px}.installation-filter-search input{width:100%}.installation-filter-bar .btn{height:40px}
.installation-table-footer{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;margin-top:18px;color:#6b7280;font-size:13px}
.installation-editor-layout{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(300px,.7fr);gap:22px;align-items:start}.installation-editor-layout>.card{min-width:0}
.installation-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.installation-form-grid .form-group{display:flex;flex-direction:column;gap:8px;min-width:0}.installation-form-grid .full-width{grid-column:1/-1}
.installation-form-grid label{font-size:13px;font-weight:600;color:#334155}.installation-form-grid input,.installation-form-grid select,.installation-form-grid textarea{width:100%;min-height:42px;padding:10px 12px;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:7px;background:#fff;color:#1e293b;font:inherit;font-size:13px}.installation-form-grid textarea{resize:vertical;line-height:1.6}.installation-form-grid input:focus,.installation-form-grid select:focus,.installation-form-grid textarea:focus{outline:none;border-color:#2563eb;box-shadow:0 0 0 3px #2563eb1a}.installation-form-grid :is(input,select)[readonly],.installation-form-grid select:disabled{background:#f8fafc;color:#64748b}.installation-form-grid .form-hint,.installation-form-grid small{font-size:11px;line-height:1.6;color:#64748b}.installation-form-grid .field-error{color:#dc2626}.installation-form-grid .required,.required-mark{color:#dc2626}
.installation-form-section+.installation-form-section{margin-top:30px;padding-top:26px;border-top:1px solid #e2e8f0}.installation-section-heading{margin-bottom:20px}.installation-section-heading h4{font-size:15px;font-weight:600;margin:0 0 6px;color:#1e293b}.installation-section-heading p{font-size:13px;color:#64748b;margin:0;line-height:1.6}.installation-form-actions{display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap;margin-top:30px;padding-top:22px;border-top:1px solid #e2e8f0}
.installation-preview{position:sticky;top:88px;border:1px solid #e3e8ef;border-radius:12px;padding:24px;background:#fafbfd;box-sizing:border-box}.installation-preview .preview-eyebrow{font-size:10px;letter-spacing:1px;font-weight:700;color:#8190a3;margin-bottom:20px}.installation-preview .preview-head{display:flex;align-items:center;gap:12px;padding-bottom:18px;border-bottom:1px solid #e3e8ef}.installation-preview .preview-symbol{width:42px;height:42px;display:grid;place-items:center;border-radius:10px;background:#e5f5ef;color:#128165;font-size:23px}.installation-preview .preview-head h3{margin:0 0 5px;color:#17284f;font-size:16px}.installation-preview .preview-head small{font-size:11px;color:#8792a5}.installation-preview .preview-line{display:flex;justify-content:space-between;gap:14px;padding:13px 0;border-bottom:1px solid #e8edf3;font-size:11px}.installation-preview .preview-line span{color:#8390a3}.installation-preview .preview-line strong{text-align:right;overflow-wrap:anywhere;font-size:12px;color:#17284f}.installation-preview .preview-notice{background:#edf4f3;color:#57746c;padding:12px;border-radius:8px;font-size:11px;line-height:1.6;margin-top:18px}
.installation-info-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.installation-info-grid .info-field{display:flex;flex-direction:column;align-items:flex-start;gap:8px;min-width:0}.installation-info-grid .full-width{grid-column:1/-1}.installation-info-grid .info-label{font-size:13px;color:#64748b}.installation-info-grid .info-value{font-size:14px;font-weight:600;color:#1e293b;overflow-wrap:anywhere}.installation-info-grid .info-long{white-space:pre-line;line-height:1.7;font-weight:400}
.installation-badge{display:inline-flex;align-items:center;justify-content:center;width:max-content;border-radius:20px;border:1px solid transparent;padding:5px 10px;font-size:11px;font-weight:600;white-space:nowrap}.installation-badge.warning{color:#92400e;background:#fef3c7;border-color:#fde68a}.installation-badge.info{color:#1d4ed8;background:#dbeafe;border-color:#bfdbfe}.installation-badge.success{color:#166534;background:#dcfce7;border-color:#bbf7d0}.installation-badge.danger{color:#991b1b;background:#fee2e2;border-color:#fecaca}.installation-badge.secondary{color:#475569;background:#f1f5f9;border-color:#e2e8f0}
.installation-progress-heading{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:10px;font-size:12px;color:#17284f}.installation-progress-track{height:10px;background:#e8eef3;border-radius:99px;overflow:hidden}.installation-progress-fill{height:100%;background:#16856a;transition:width .25s}.installation-status-actions{display:flex;align-items:center;flex-wrap:wrap;gap:9px;margin-top:20px}.installation-muted{font-size:12px;color:#718096;line-height:1.6}
.installation-checklist-note{max-width:300px;min-width:190px}.installation-checklist-note textarea{display:block;width:100%;min-height:70px;padding:9px 11px;border:1px solid #d9dee8;border-radius:7px;font:inherit;font-size:12px;line-height:1.6;resize:vertical;box-sizing:border-box;background:#fff}.installation-checklist-note textarea:focus{outline:none;border-color:#2563eb;box-shadow:0 0 0 3px #2563eb1a}.installation-checklist-note .note-actions{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:8px}.installation-checklist-note .note-actions .btn{font-size:11px}.installation-checklist-note .note-hint{font-size:10px;color:#718096;margin-top:5px}.installation-checklist-note .saved-note{white-space:pre-wrap;color:#34415c;font-size:12px;line-height:1.6}
.installation-confirm[hidden]{display:none!important}.installation-confirm{position:fixed;inset:0;z-index:20000;display:flex;align-items:center;justify-content:center;background:#0e1c3694;padding:18px}.installation-confirm-dialog{width:min(100%,440px);background:white;border-radius:16px;box-sizing:border-box;padding:29px;box-shadow:0 22px 70px #14203738;text-align:center}.installation-confirm-symbol{display:grid;place-items:center;width:54px;height:54px;margin:0 auto 15px;border-radius:15px;background:#edf4f3;color:#16856a;font-size:24px;font-weight:800}.installation-confirm-dialog h3{font-size:19px;color:#17284f;margin:0 0 9px}.installation-confirm-dialog p{font-size:13px;color:#667085;line-height:1.6;margin:0 0 22px}.installation-confirm-actions{display:flex;justify-content:center;gap:9px;flex-wrap:wrap}.installation-delete-confirm{background:#c94a4a!important;color:#fff!important;border-color:#c94a4a!important}
.installation-toast{position:fixed;top:22px;left:50%;transform:translateX(-50%);z-index:19000;min-width:260px;max-width:min(90vw,600px);padding:14px 20px;border-radius:10px;box-shadow:0 8px 30px #0002;font-size:13px;font-weight:600;animation:installation-toast-fade .45s ease 4s forwards}.installation-toast.success{background:#e7f8ef;color:#106c48;border:1px solid #95d5b4}.installation-toast.danger{background:#fff0f0;color:#9f2323;border:1px solid #f0b9b9}@keyframes installation-toast-fade{to{opacity:0;visibility:hidden}}
@media(max-width:1050px){.installation-editor-layout{grid-template-columns:1fr}.installation-preview{position:static}}
@media(max-width:768px){.installation-form-grid,.installation-info-grid{grid-template-columns:1fr}.installation-form-grid .full-width,.installation-info-grid .full-width{grid-column:auto}.installation-filter-bar{flex-direction:column;align-items:stretch}.installation-filter-search,.installation-filter-bar select,.installation-filter-bar .btn{width:100%}}
@media(max-width:480px){.installation-form-actions{flex-direction:column-reverse}.installation-form-actions .btn{width:100%}}

/* Installation warranty activation — uses the existing Delivery-like card and modal */
.installation-warranty-card{margin-top:18px;margin-bottom:18px}
.installation-warranty-card .card-body>.installation-muted{margin:0 0 16px}
.installation-warranty-card .installation-warranty-trigger{margin-top:16px}
.installation-warranty-card .installation-table{min-width:690px}

</style>
